'use strict';
// Arena Clash: self-unpacking server. The game files are inside this file; on start they are written to ./_app and run from there.
const fs = require('fs'), path = require('path'), zlib = require('zlib'), crypto = require('crypto');
const PAYLOAD = '';
const gz = Buffer.from(PAYLOAD, 'base64');
if (crypto.createHash('sha256').update(gz).digest('hex') !== '5220ff13c1222fb3c3b4f288c196461aa94e4d7d1923f9f89b17edfe4269696a') { console.error('app.js is damaged (it was not copied completely). Upload the original file again.'); process.exit(1); }
const files = JSON.parse(zlib.gunzipSync(gz).toString()), dir = path.join(__dirname, '_app');
for (const [rel, b] of Object.entries(files)) { const p = path.join(dir, rel); fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, Buffer.from(b, 'base64')); }
require(path.join(dir, 'server.js'));
